interface.definition:
a!localVariables(

  #"SYSTEM_SYSRULES_formLayout_v1"(
    label: #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12256661"[1],
    instructions: "Use this page to deactivate user from this application.",
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: #"SYSTEM_SYSRULES_columnLayout"(
          width: "MEDIUM_PLUS",
          contents: {
            #"SYSTEM_SYSRULES_pickerFieldUsers"(
              label: #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12256661"[3],
              labelPosition: "ABOVE",
              value: ri!deactivatedUsers,
              saveInto: ri!deactivatedUsers,
              required: true,
              groupFilter: #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12219526",
              requiredmessage: "Select Users to Deactivate",
              maxSelections: 1,
              validations: {
                if(
                  ri!deactivatedUsers = loggedInUser(),
                  #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12256667"[1],
                  {}
                )
              }
            ),

          }
        )
      )/*a!pickerFieldUsers(*/
      /*label: cons!CAW_LABEL_FOR_DEACTIVATE_USER[3],*/
      /*labelPosition: "ABOVE",*/
      /*value: ri!deactivatedUsers,*/
      /*saveInto: ri!deactivatedUsers,*/
      /*required: true,*/
      /*groupFilter: cons!CAW_GRP_USER,*/
      /*requiredmessage: "Select Users to Deactivate",*/
      /*maxSelections: 1,*/
      /*validations: if(*/
      /*ri!deactivatedUsers = loggedInUser(),*/
      /*cons!CAW_VALIDATION_MESSAGE_FOR_DEACTIVATE_USER[1],*/
      /*{}*/
      /*)*/
      /*),*/
      /*a!textField(*/
      /*label: "RITM",*/
      /*labelPosition: "ABOVE",*/
      /*required: cons!CAW_RITM_REQUIRED_CONSTANT,*/
      /*requiredMessage: "Please Enter the Value",*/
      /*value: ri!ritm,*/
      /*saveInto: ri!ritm,*/
      /*refreshAfter: "KEYPRESS",*/
      /*characterLimit: 15*/
      /*)*/

    },
    buttons: {
      #"SYSTEM_SYSRULES_ButtonLayout"(
        primaryButtons: {
          #"SYSTEM_SYSRULES_ButtonWidgetSubmit"(
            label: "REMOVE",
            value: "REMOVE",
            saveInto: { ri!buttonValue,  },
            style: "DESTRUCTIVE",
            disabled: a!isNullOrEmpty(ri!deactivatedUsers),
            confirmheader: " Are you sure you want to remove this user?",

          )
        },
        secondaryButtons: #"SYSTEM_SYSRULES_ButtonWidgetSubmit"(
          label: "Cancel",
          value: "CANCEL",
          saveInto: ri!buttonValue,
          skipValidation: true,
          confirmheader: " Are you sure you want to cancel ?",

        )
      )
    }
  )
)
